/* Shim versions of the few xscreensaver utils helpers that hacks call.
 * Written for this project; not derived from xscreensaver's utils. */
#include <math.h>
#include <stdlib.h>

#include "alpha.h"
#include "colors.h"
#include "erase.h"
#include "hsv.h"

static double frand_unit(void) {
  return (double)random() / ((double)RAND_MAX + 1.0);
}

/* No wipe animation: clear the window and report that erasing is done. */
eraser_state *erase_window(Display *dpy, Window w, eraser_state *st) {
  (void)st;
  XClearWindow(dpy, w);
  return NULL;
}

void eraser_free(eraser_state *st) { (void)st; }

Bool has_writable_cells(Screen *screen, Visual *visual) {
  (void)screen, (void)visual;
  return False;
}

void make_random_colormap(Screen *screen, Visual *visual, Colormap cmap,
                          XColor *colors, int *ncolorsP, Bool bright_p,
  struct xscreensaver_function_table *t = e->xsft;
  if (!t) return (Callbacks){e->defaults, e->init, e->draw, e->free, NULL, 0};
  if (!t->init_cb && t->setup_cb) t->setup_cb(t, t->setup_arg);
  return (Callbacks){t->defaults, t->init_cb, t->draw_cb, t->free_cb,
                     t->setup_arg, 1};
}

static void stop(HackRunner *r) {
  if (!r->running) return;
  callbacks_for(r->hacks[r->index]).free(r->dpy, XSHIM_WINDOW, r->closure);
  /* The display outlives the hack, so release what the hack forgot to free, as
   * an X server does when a client disconnects. */
  xshim_release_pixmaps(r->dpy);
  r->closure = NULL;
  r->running = 0;
}

void runner_destroy(HackRunner *r) {
  if (!r) return;
  stop(r);
  xshim_close_display(r->dpy);
